-- Hindi copy for collections and products (run after schema.sql).
alter table collections add column if not exists tagline_hi text, add column if not exists headline_hi text, add column if not exists description_hi text, add column if not exists story_hi text, add column if not exists meaning_hi text;
alter table products add column if not exists tagline_hi text, add column if not exists description_hi text, add column if not exists long_description_hi text;
update collections set tagline_hi='स्थिरता का लोक', headline_hi='अचल बिंदु बनिए।', description_hi='घूमते आकाश का स्थिर बिंदु। गहनतम नील पर उभरा स्वर्णिम दिशासूचक, उनके लिए जो अपनी दिशा थामे रखते हैं।', meaning_hi='ध्रुव · अचल · ध्रुव तारा', story_hi='ध्रुव एक बालक था, जो तब तक स्थिर बैठा रहा जब तक आकाश ने उसे वह स्थान नहीं दे दिया जो कभी नहीं डिगता। तब से प्रत्येक नाविक और मनीषी ने उसी तारे के सहारे दिशा पाई है। हमने पूछा कि कलाई पर एक अचल बिंदु कैसा दिखेगा, और उभरे स्वर्ण में एक दिशासूचक रचा, जिसमें सप्तर्षि के सात तारे दृष्टि को उत्तर की ओर ले जाते हैं। डायल नीलवर्ण है, सूर्यास्त के ठीक पश्चात की वह बेला जब पहला तारा प्रकट होता है। ध्रुव स्थिरता का लोक है: उनके लिए जो संसार के घूमते रहने पर भी अपनी दिशा के प्रति सच्चे रहते हैं। यह प्रथम युग की प्रथम घड़ी है, और वह जो अपनी दिशा कभी नहीं खोती।' where slug='dhruv';
update collections set tagline_hi='प्रकाश का लोक', headline_hi='अपना प्रकाश स्वयं धारण कीजिए।', description_hi='श्याम पर तपे हुए स्वर्ण की बारह किरणें, उस सूर्य को अर्पण जो संसार को जगाता है।', meaning_hi='सूर्य · तेज के दाता', story_hi='वेद अपने सूक्तों का आरंभ सूर्य से करते हैं, उस सूर्य से जो संसार को जगाता है। परंपरा बारह आदित्य गिनती है, सूर्य के बारह स्वरूप, प्रत्येक मास के लिए एक। हमने डायल को बारह उभरी किरणें दीं, छह सीधी स्थिर प्रकाश के लिए और छह लहरदार ऊष्मा के लिए, जो एक स्वर्ण मंडल के चारों ओर बारी-बारी से सजती हैं। हमने इसे श्याम पर स्थापित किया, क्योंकि वास्तविक आकाश में सूर्य एक विशाल अंधकार में प्रकाश का अकेला स्रोत है। सूर्य प्रकाश का लोक है: उनके लिए जो प्रज्वलित किए जाने की प्रतीक्षा नहीं करते, और अपना तेज हर सभा में साथ लिए चलते हैं।' where slug='surya';
update collections set tagline_hi='नियति का लोक', headline_hi='कुछ बातें लिखी जा चुकी हैं।', description_hi='सत्ताईस तारे, चंद्रमा की लंबी यात्रा की प्रत्येक रात्रि के लिए एक, अनुष्ठान के गहरे रक्तवर्ण पर अंकित।', meaning_hi='नक्श · एक चिह्न, एक छाप · सत्ताईस नक्षत्रों की प्रतिध्वनि', story_hi='प्राचीन आकाश-द्रष्टाओं ने चंद्रमा के पथ को सत्ताईस नक्षत्रों में विभाजित किया, उसकी यात्रा की प्रत्येक रात्रि के लिए एक विश्राम-स्थल। हमने सभी सत्ताईस को उभरे अष्टकोणीय तारों के रूप में एक अविच्छिन्न वलय में स्थापित किया, शीर्ष पर अश्विनी से आरंभ करते हुए, एक शांत स्वर्ण केंद्र के चारों ओर। नक्श का अर्थ है एक चिह्न, एक छाप, और यही हमारा अभिप्राय है: एक आकृति जो बनी रहे। डायल गहरे रक्तवर्ण का है, अनुष्ठान, उत्सव और लंबी संध्याओं का रंग। नक्श नियति का लोक है: उनके लिए जो मानते हैं कि कुछ बातें लिखी जा चुकी हैं, और जो उसका प्रमाण धारण करते हैं।' where slug='naksh';
update collections set tagline_hi='अंतरिक्ष का लोक', headline_hi='ऊपर देखते रहिए।', description_hi='नौ ज्योतिर्मय पिंड अपनी नियत कक्षाओं में, खुले आकाश की हरित निस्तब्धता में स्थित।', meaning_hi='व्योम · आकाश, अंतरिक्ष, अनंत आकाश-तत्त्व', story_hi='व्योम खुला आकाश है, वह तत्त्व जो सब कुछ धारण करता है। वैदिक खगोलविदों ने नौ पिंडों का अनुसरण किया, नवग्रह: सूर्य, चंद्र, पाँच दृश्य ग्रह और दो चंद्र-बिंदु। हमने उन्हें एक धारीदार गोले के चारों ओर कक्षा-वलयों पर नौ स्वर्ण मणियों के रूप में रचा, ताकि संपूर्ण आकाश कलाई पर एक यंत्र की भाँति पढ़ा जा सके। डायल गहरा हरित है, वर्षा के पश्चात पत्तों के बीच से दिखता आकाश। व्योम अंतरिक्ष का लोक है: उनके लिए जो आज भी ऊपर देखते हैं, और जानते हैं कि गहराई स्वयं एक प्रकार की विलासिता है।' where slug='vyom';
update collections set tagline_hi='लय का लोक', headline_hi='चक्रों में शांति।', description_hi='तीस चांद्र तिथियाँ एक रजत अर्धचंद्र को घेरे हुए, चाँदनी में नहाए पत्थर-से शांत धूसर पटल पर।', meaning_hi='सोम · चंद्रमा, और वेदों का दीप्तिमान पेय', story_hi='ऋग्वेद एक संपूर्ण मंडल सोम को अर्पित करता है, चंद्रमा को और देवताओं के दीप्तिमान पेय को। चांद्र मास की गणना तीस तिथियों में होती है, पंद्रह जब चंद्रमा बढ़ता है और पंद्रह जब घटता है। हमने तीस बिंदु एक वलय में स्थापित किए, पंद्रह उज्ज्वल और पंद्रह श्याम, एक गढ़े हुए रजत अर्धचंद्र के चारों ओर। डायल धूसर है, चाँदनी में नहाया पत्थर, और अलंकरण केवल रजत का है, क्योंकि चंद्रमा के पास स्वर्ण नहीं होता। सोम लय का लोक है: उनके लिए जो चक्रों में शांति पाते हैं, और विश्वास रखते हैं कि सब कुछ अपने समय पर लौट आता है।' where slug='soma';
update products set tagline_hi='स्थिरता, श्याम में।', description_hi='गहनतम अंधकार में स्थिरता। श्याम आवरण, श्याम पट्टा, उभरे हुए नील डायल पर दिशासूचक। जापानी क्वार्ट्ज़।', long_description_hi='गहनतम अंधकार में स्थिरता। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Dhruv Night युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='dhruv-night';
update products set tagline_hi='सप्तर्षि उत्तर की ओर संकेत करते हैं।', description_hi='रजत और नील, भोर से पहले की शीतल निर्मल वायु। रजत आवरण, नील पट्टा, उभरे हुए नील डायल पर दिशासूचक। जापानी क्वार्ट्ज़।', long_description_hi='रजत और नील, भोर से पहले की शीतल निर्मल वायु। रजत टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। नील सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Dhruv North युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='dhruv-north';
update products set tagline_hi='एक अचल तारा, स्वर्ण में धारण किया हुआ।', description_hi='ध्रुव तारा, मानो उसे हाथ में थामा जा सके। स्वर्ण आवरण, भूरा पट्टा, उभरे हुए नील डायल पर दिशासूचक। जापानी क्वार्ट्ज़।', long_description_hi='ध्रुव तारा, मानो उसे हाथ में थामा जा सके। स्वर्ण टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। भूरा सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Dhruv Star युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='dhruv-star';
update products set tagline_hi='सूर्य, छाया में सहेजा हुआ।', description_hi='श्याम पर श्याम, केवल स्वर्ण शेष। श्याम आवरण, श्याम पट्टा, श्याम डायल पर उभरा स्वर्णिम सूर्य। जापानी क्वार्ट्ज़।', long_description_hi='श्याम पर श्याम, केवल स्वर्ण शेष। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Surya Eclipse युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='surya-eclipse';
update products set tagline_hi='एक सूर्य। बारह किरणें। स्वर्ण में।', description_hi='पूर्ण तेज में सूर्य। स्वर्ण आवरण, श्याम पट्टा, श्याम डायल पर उभरा स्वर्णिम सूर्य। जापानी क्वार्ट्ज़।', long_description_hi='पूर्ण तेज में सूर्य। स्वर्ण टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Surya Radiance युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='surya-radiance';
update products set tagline_hi='प्रथम किरण, सहेजी हुई।', description_hi='स्वर्ण और उष्ण भूरा, धरती पर प्रातःकाल की पहली घड़ी के रंग। स्वर्ण आवरण, भूरा पट्टा, श्याम डायल पर उभरा स्वर्णिम सूर्य। जापानी क्वार्ट्ज़।', long_description_hi='स्वर्ण और उष्ण भूरा, धरती पर प्रातःकाल की पहली घड़ी के रंग। स्वर्ण टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। भूरा सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Surya Sunrise युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='surya-sunrise';
update products set tagline_hi='दिन का अंतिम स्वर्ण।', description_hi='श्याम आवरण और उष्ण भूरा पट्टा, दिन के अंत में नीचे उतरा भारी सूर्य। श्याम आवरण, भूरा पट्टा, श्याम डायल पर उभरा स्वर्णिम सूर्य। जापानी क्वार्ट्ज़।', long_description_hi='श्याम आवरण और उष्ण भूरा पट्टा, दिन के अंत में नीचे उतरा भारी सूर्य। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। भूरा सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Surya Dusk युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='surya-dusk';
update products set tagline_hi='एक अकेली किरण, रजत में तराशी हुई।', description_hi='मध्याह्न के निर्मल प्रकाश के लिए शीतल रजत। रजत आवरण, श्याम पट्टा, श्याम डायल पर उभरा स्वर्णिम सूर्य। जापानी क्वार्ट्ज़।', long_description_hi='मध्याह्न के निर्मल प्रकाश के लिए शीतल रजत। रजत टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Surya Ray युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।' where slug='surya-ray';
