insert into site_settings(key,value) values ('ticker_hi', to_jsonb('कालातीतता का अस्त्र ✦ आकाश में लिखा समय ✦ क्षण से परे टिकने के लिए रचित ✦ कालजयी · समय से परे ✦ सहेजने योग्य एक कृति'::text)) on conflict (key) do update set value=excluded.value;

-- Water resistance (5 ATM) and strap width on every watch
update products set specs = coalesce(specs,'{}'::jsonb) || '{"Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb
  where not (coalesce(specs,'{}'::jsonb) ? 'Water resistance');
update products set specs = specs || '{"Fits wrists":"14–20 cm"}'::jsonb where not (specs ? 'Fits wrists');
update products set features = coalesce(features,'[]'::jsonb) || '["Water resistant to 5 ATM (50 m)"]'::jsonb
  where not (coalesce(features,'[]'::jsonb) ? 'Water resistant to 5 ATM (50 m)');
